import React from "react";
import { Input } from "@/components/ui/input";
import { Trash2 } from "lucide-react";

const money = (n) => `$${Number(n || 0).toFixed(2)}`;
const selectCls = "flex h-9 w-full rounded-md border border-input bg-transparent px-2 text-sm";

const ITEM_TYPES = [
  { value: "panel", label: "Panel / Shape (cut)" },
  { value: "lettering", label: "Lettering (cut)" },
  { value: "engraving", label: "Engraving only" },
  { value: "engrave_and_cut", label: "Engrave + Cut" },
];
const MATERIALS = ["Acrylic", "Wood", "Leather"];

export default function LaserItemCard({ item, index, onChange, onRemove }) {
  const set = (patch) => onChange(index, patch);
  const type = item.item_type || "panel";
  const doesEngrave = type === "engraving" || type === "engrave_and_cut";
  const doesCut = type !== "engraving";

  const numField = (key, label) => (
    <label className="text-xs text-gray-500">
      {label}
      <Input
        type="number"
        value={item[key] ?? 0}
        onChange={(e) => set({ [key]: parseFloat(e.target.value) || 0 })}
      />
    </label>
  );

  return (
    <div className="bg-white rounded-xl border border-gray-200 p-4 space-y-3">
      <div className="flex items-start gap-2">
        <Input
          value={item.description || ""}
          placeholder="Part description"
          onChange={(e) => set({ description: e.target.value })}
        />
        <button onClick={() => onRemove(index)} className="text-gray-400 hover:text-red-600 p-2">
          <Trash2 className="w-4 h-4" />
        </button>
      </div>

      <div className="grid grid-cols-1 sm:grid-cols-3 gap-3">
        <label className="text-xs text-gray-500">
          Item type
          <select
            value={type}
            onChange={(e) => set({ item_type: e.target.value })}
            className={selectCls}
          >
            {ITEM_TYPES.map((t) => (
              <option key={t.value} value={t.value}>
                {t.label}
              </option>
            ))}
          </select>
        </label>
        <label className="text-xs text-gray-500">
          Material
          <select
            value={item.material_type || "Acrylic"}
            onChange={(e) => set({ material_type: e.target.value })}
            className={selectCls}
          >
            {MATERIALS.map((m) => (
              <option key={m} value={m}>
                {m}
              </option>
            ))}
          </select>
        </label>
        <label className="text-xs text-gray-500">
          Thickness
          <Input
            value={item.material_thickness || ""}
            placeholder='e.g. 1/8"'
            onChange={(e) => set({ material_thickness: e.target.value })}
          />
        </label>
      </div>

      <div className="grid grid-cols-2 sm:grid-cols-4 gap-3">
        {numField("quantity", "Qty")}
        {doesEngrave && numField("engrave_area_sqin", "Engrave area (sq in)")}
        {doesEngrave && numField("engrave_speed_sqipm", "Engrave sq in/min")}
        {doesCut && type === "lettering" && numField("num_letters", "# Letters")}
        {doesCut && type === "lettering" && numField("letter_height", "Letter height (in)")}
        {doesCut && type !== "lettering" && numField("length", "Length (in)")}
        {doesCut && type !== "lettering" && numField("width", "Width (in)")}
        {doesCut && numField("cut_speed_ipm", "Cut speed (ipm)")}
        {doesCut && numField("total_cut_length_inches", "Cut length override (in)")}
      </div>

      <div className="flex flex-wrap gap-x-4 text-xs text-gray-500 border-t border-gray-100 pt-2">
        <span>Engrave {Number(item.engrave_hours || 0).toFixed(2)} hr</span>
        <span>Cut {Number(item.cut_hours || 0).toFixed(2)} hr</span>
        <span>
          {money(item.machine_cost)} machine · {money(item.labor_cost)} labor
        </span>
        <span className="font-semibold text-gray-900 ml-auto">{money(item.item_total_cost)}</span>
      </div>
    </div>
  );
}

const num = (v, d = 0) => (Number.isFinite(Number(v)) ? Number(v) : d);

// Engraving items run on the engraving laser; cutting items run on the parameter laser.
// engrave_and_cut splits: engrave portion on the engraving laser, cut portion on the parameter laser.
export function calcLaserProject(project) {
  const cutMachine = num(project.machine_rate_per_hour, 100);
  const cutLabor = num(project.labor_rate, 75);
  const engMachine = num(project.engraving_machine_rate_per_hour, 80);
  const engLabor = num(project.engraving_labor_rate, 40);
  const cutHandlingPct = num(project.parameter_handling_time_percentage, 15);
  const engHandlingPct = num(project.engraving_handling_time_percentage, 20);

  const items = (project.items || []).map((raw) => {
    const item = { ...raw };
    const qty = num(item.quantity, 1);
    const type = item.item_type || "panel";
    const doesEngrave = type === "engraving" || type === "engrave_and_cut";
    const doesCut = type !== "engraving";

    const engSpeed = num(item.engrave_speed_sqipm, 5);
    const engHours = doesEngrave && engSpeed > 0 ? (num(item.engrave_area_sqin) / engSpeed / 60) * qty : 0;

    const cutSpeed = num(item.cut_speed_ipm, 20);
    const perimeter =
      num(item.total_cut_length_inches) ||
      (type === "lettering"
        ? num(item.num_letters) * num(item.letter_height) * 4
        : (num(item.length) + num(item.width)) * 2);
    const cutHours = doesCut && cutSpeed > 0 ? (perimeter / cutSpeed / 60) * qty : 0;

    item.engrave_hours = engHours;
    item.cut_hours = cutHours;
    item.machine_time_hours = engHours + cutHours;
    item.handling_time_hours =
      (engHours * engHandlingPct) / 100 + (cutHours * cutHandlingPct) / 100;
    item.machine_cost = engHours * engMachine + cutHours * cutMachine;
    item.labor_cost =
      ((engHours * engHandlingPct) / 100) * engLabor + ((cutHours * cutHandlingPct) / 100) * cutLabor;
    item.item_total_cost = item.machine_cost + item.labor_cost;
    return item;
  });

  const total_machine_hours = items.reduce((s, i) => s + i.machine_time_hours, 0);
  const total_handling_hours =
    items.reduce((s, i) => s + i.handling_time_hours, 0) + num(project.fixed_setup_hours);
  const total_machine_cost = items.reduce((s, i) => s + i.machine_cost, 0);
  const fixed_setup_cost = num(project.fixed_setup_hours) * cutLabor;
  const total_labor_cost = items.reduce((s, i) => s + i.labor_cost, 0) + fixed_setup_cost;
  const total_supplies_cost = num(project.fixed_material_setup_cost);

  return {
    items,
    totals: {
      total_machine_hours,
      total_handling_hours,
      total_machine_cost,
      fixed_setup_cost,
      total_labor_cost,
      total_supplies_cost,
      total_cost: total_machine_cost + total_labor_cost + total_supplies_cost,
    },
  };
}

import React from "react";
import { Input } from "@/components/ui/input";
import { Trash2 } from "lucide-react";

const money = (n) => `$${Number(n || 0).toFixed(2)}`;
const selectCls = "flex h-9 w-full rounded-md border border-input bg-transparent px-2 text-sm";

const ITEM_TYPES = [
  "channel_letters",
  "cabinet_sign",
  "monument_sign",
  "pole_sign",
  "flat_cut_letters",
  "fabricated_letters",
  "frame_assembly",
  "custom_brackets",
];
const labelFor = (t) => t.replace(/_/g, " ").replace(/\b\w/g, (c) => c.toUpperCase());

const invLabel = (inv) =>
  `${inv.material_type?.replace(/_/g, " ")} ${inv.product_type?.replace(/_/g, " ")} ${inv.size}${
    inv.thickness_gauge ? ` (${inv.thickness_gauge})` : ""
  } — $${Number(inv.cost_per_unit || 0).toFixed(2)} ${inv.unit_type?.replace("per_", "/")}`;

export default function MetalItemCard({ item, index, inventory, onChange, onRemove }) {
  const set = (patch) => onChange(index, patch);

  const numField = (key, label) => (
    <label className="text-xs text-gray-500">
      {label}
      <Input
        type="number"
        value={item[key] ?? 0}
        onChange={(e) => set({ [key]: parseFloat(e.target.value) || 0 })}
      />
    </label>
  );

  return (
    <div className="bg-white rounded-xl border border-gray-200 p-4 space-y-3">
      <div className="flex items-start gap-2">
        <Input
          value={item.description || ""}
          placeholder="Item description"
          onChange={(e) => set({ description: e.target.value })}
        />
        <button onClick={() => onRemove(index)} className="text-gray-400 hover:text-red-600 p-2">
          <Trash2 className="w-4 h-4" />
        </button>
      </div>

      <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
        <label className="text-xs text-gray-500">
          Item type
          <select
            value={item.item_type || "channel_letters"}
            onChange={(e) => set({ item_type: e.target.value })}
            className={selectCls}
          >
            {ITEM_TYPES.map((t) => (
              <option key={t} value={t}>
                {labelFor(t)}
              </option>
            ))}
          </select>
        </label>
        <label className="text-xs text-gray-500">
          Material from inventory
          <select
            value={item.inventory_item_id || ""}
            onChange={(e) => set({ inventory_item_id: e.target.value })}
            className={selectCls}
          >
            <option value="">— none —</option>
            {inventory.map((inv) => (
              <option key={inv.id} value={inv.id}>
                {invLabel(inv)}
              </option>
            ))}
          </select>
        </label>
      </div>

      <div className="grid grid-cols-2 sm:grid-cols-5 gap-3">
        {numField("quantity", "Qty")}
        {numField("material_length_ft", "Material (ft)")}
        {numField("fabrication_hours", "Fab hrs")}
        {numField("welding_hours", "Weld hrs")}
        {numField("finishing_hours", "Finish hrs")}
      </div>

      <div className="flex flex-wrap gap-x-4 text-xs text-gray-500 border-t border-gray-100 pt-2">
        <span>{money(item.material_cost)} material</span>
        <span>{money(item.supplies_cost)} supplies</span>
        <span>
          {money(
            Number(item.fabrication_cost || 0) +
              Number(item.welding_cost || 0) +
              Number(item.finishing_cost || 0)
          )}{" "}
          labor
        </span>
        <span className="font-semibold text-gray-900 ml-auto">{money(item.item_total_cost)}</span>
      </div>
    </div>
  );
}

const num = (v, d = 0) => (Number.isFinite(Number(v)) ? Number(v) : d);

function materialCostFor(inv, item) {
  if (!inv) return 0;
  const rate = num(inv.cost_per_unit);
  const lengthFt = num(item.material_length_ft);
  switch (inv.unit_type) {
    case "per_piece": {
      const stock = num(inv.standard_length, 0);
      const pieces = stock > 0 && lengthFt > 0 ? Math.ceil(lengthFt / stock) : 1;
      return rate * pieces;
    }
    case "per_pound":
    case "per_sqft":
      return rate * (lengthFt || 1);
    case "per_foot":
    default:
      return rate * lengthFt;
  }
}

export function calcMetalProject(project, inventoryById = {}) {
  const fabRate = num(project.fabrication_rate, 65);
  const weldRate = num(project.welding_rate, 75);
  const finRate = num(project.finishing_rate, 55);
  const suppliesPct = num(project.supplies_percent_of_materials, 8);

  const items = (project.items || []).map((raw) => {
    const item = { ...raw };
    const qty = num(item.quantity, 1);
    const inv = inventoryById[item.inventory_item_id];

    item.material_cost = materialCostFor(inv, item) * qty;
    item.supplies_cost = (item.material_cost * suppliesPct) / 100;
    item.fabrication_cost = num(item.fabrication_hours) * qty * fabRate;
    item.welding_cost = num(item.welding_hours) * qty * weldRate;
    item.finishing_cost = num(item.finishing_hours) * qty * finRate;
    item.item_total_cost =
      item.material_cost +
      item.supplies_cost +
      item.fabrication_cost +
      item.welding_cost +
      item.finishing_cost;
    return item;
  });

  const sum = (key) => items.reduce((s, i) => s + num(i[key]), 0);
  const total_material_cost = sum("material_cost");
  const total_supplies_cost = sum("supplies_cost") + num(project.extra_supplies_cost);
  const total_fabrication_cost = sum("fabrication_cost");
  const total_welding_cost = sum("welding_cost");
  const total_finishing_cost = sum("finishing_cost");

  const subtotal =
    total_material_cost +
    total_supplies_cost +
    total_fabrication_cost +
    total_welding_cost +
    total_finishing_cost;
  const markup_amount = (subtotal * num(project.markup_percent)) / 100;

  return {
    items,
    totals: {
      total_labor_hours: items.reduce(
        (s, i) =>
          s +
          (num(i.fabrication_hours) + num(i.welding_hours) + num(i.finishing_hours)) *
            num(i.quantity, 1),
        0
      ),
      total_material_cost,
      total_supplies_cost,
      total_fabrication_cost,
      total_welding_cost,
      total_finishing_cost,
      subtotal,
      markup_amount,
      total_cost: subtotal + markup_amount,
    },
  };
}
